/* Focused compile/behaviour check for the statements added to
 * drivers/net/wireless/rtlwifi/ps.c (CVE-2019-17666 / rtlwifi P2P NOA).
 *
 * This is NOT the kernel module build. It isolates the exact added
 * statements and the surrounding arithmetic so that:
 *   - the added statements compile as C with the target types;
 *   - the pre-fix arithmetic can overflow the P2P_MAX_NOA_NUM-sized arrays;
 *   - the post-fix arithmetic cannot.
 * Types are copied from the target code: noa_num is u8, noa_len is u16,
 * P2P_MAX_NOA_NUM is 2, arrays hold P2P_MAX_NOA_NUM entries.
 */

#include <stdio.h>
#include <stdint.h>

typedef uint8_t  u8;
typedef uint16_t u16;
typedef uint32_t u32;

#define P2P_MAX_NOA_NUM 2

struct rtl_p2p_ps_info {
	u8  noa_count_type[P2P_MAX_NOA_NUM];
	u32 noa_duration[P2P_MAX_NOA_NUM];
	u32 noa_interval[P2P_MAX_NOA_NUM];
	u32 noa_start_time[P2P_MAX_NOA_NUM];
	u8  noa_num;
};

/* count writes performed by the loop `for (i = 0; i < noa_num; i++)`
 * writing all four arrays; returns 1 if an index >= P2P_MAX_NOA_NUM
 * would be written (out-of-bounds). */
static int writes_oob(u8 noa_num)
{
	int i;
	for (i = 0; i < noa_num; i++) {
		if (i >= P2P_MAX_NOA_NUM)
			return 1;
	}
	return 0;
}

/* pre-fix computation, exactly as target line 803/897 */
static u8 compute_prefix(u16 noa_len)
{
	u8 noa_num;
	noa_num = (noa_len - 2) / 13;
	return noa_num;
}

/* post-fix computation: pre-fix plus the clamp added by the candidate */
static u8 compute_fixed(u16 noa_len)
{
	u8 noa_num;
	noa_num = (noa_len - 2) / 13;
	if (noa_num > P2P_MAX_NOA_NUM)
		noa_num = P2P_MAX_NOA_NUM;
	return noa_num;
}

int main(void)
{
	/* positive path: a compatible NOA IE with noa_num <= 2 */
	u16 pos[] = { 15, 28, 2 };   /* (len-2)/13 = 1, 2, 0 */
	/* negative path: compatible length but noa_num > 2.
	 * len=41        -> (39)/13 = 3
	 * len=262       -> (260)/13 = 20, and low byte ie[1]=6 so the
	 *                  frame-availability check can pass with few bytes.
	 * len=0xffff    -> (65533)/13 = 5041, truncated to u8 => 177 */
	u16 neg[] = { 41, 262, 0xffff };
	int i, fail = 0;

	for (i = 0; i < 3; i++) {
		u8 pre = compute_prefix(pos[i]);
		u8 post = compute_fixed(pos[i]);
		printf("positive noa_len=%u pre=%u post=%u oob(pre)=%d oob(post)=%d\n",
		       pos[i], pre, post, writes_oob(pre), writes_oob(post));
		if (writes_oob(pre) || writes_oob(post))
			fail = 1;
	}
	for (i = 0; i < 3; i++) {
		u8 pre = compute_prefix(neg[i]);
		u8 post = compute_fixed(neg[i]);
		printf("negative noa_len=%u pre=%u (oob=%d) post=%u (oob=%d)\n",
		       neg[i], pre, writes_oob(pre), post, writes_oob(post));
		if (!writes_oob(pre))
			fail = 1;            /* negative path must overflow pre-fix */
		if (writes_oob(post))
			fail = 1;            /* fix must prevent overflow */
	}
	printf(fail ? "RESULT: FAIL\n" : "RESULT: PASS\n");
	return fail;
}

